function expireStalePendingDepositsInDb(nowMs = Date.now(), expiryWindowMs = DEPOSIT_EXPIRY_MS) {
  const cutoffMs = nowMs - expiryWindowMs;
  let expiredRows = [];
  try {
    expiredRows = db.prepare(
      `SELECT id FROM crypto_deposits WHERE status = 'pending' AND created_at <= ?`
    ).all(cutoffMs);
  } catch {
    expiredRows = [];
  }
  const expiredIds = expiredRows.map((r) => String(r.id));
  try {
    db.prepare(
      `UPDATE crypto_deposits
       SET status = 'failed',
           is_fulfilled = 0,
           account_id = NULL,
           processed_at = ?
       WHERE status = 'pending' AND created_at <= ?`
    ).run(nowMs, cutoffMs);
  } catch {
  }
  try {
    db.prepare(
      `UPDATE deposits
       SET status = 'failed',
           is_fulfilled = 0,
           account_id = NULL,
           decline_reason = 'Expired after 1 hour (60 minutes) without blockchain confirmation',
           processed_at = ?
       WHERE status = 'pending' AND created_at <= ?`
    ).run(nowMs, cutoffMs);
  } catch {
  }
  try {
    db.prepare(
      `UPDATE transactions
       SET status = 'failed',
           account_id = NULL,
           processed_at = ?
       WHERE status = 'pending' AND created_at <= ?`
    ).run(nowMs, cutoffMs);
  } catch {
  }
  try {
    db.prepare(
      `UPDATE user_purchases
       SET status = 'failed',
           account_id = NULL,
           processed_at = ?
       WHERE status = 'pending' AND created_at <= ?`
    ).run(nowMs, cutoffMs);
  } catch {
  }
  return {
    expiredCount: expiredIds.length,
    expiredIds,
    cutoffMs
  };
}
